-- 自动生成：官方设计系统模板种子（来源 open-design/design-systems）
-- 共 150 个模板，brandSpec v2.0
-- 幂等：ON CONFLICT (name) DO NOTHING（要求 name 上有唯一约束；若无约束请先执行 ALTER）
-- 生成器：tmp-brand-spec-generator.mjs

-- 确保 name 字段有唯一约束（幂等添加）
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'uk_dsct_name'
          AND conrelid = 'sys_design_system_config_template'::regclass
    ) THEN
        ALTER TABLE sys_design_system_config_template
          ADD CONSTRAINT uk_dsct_name UNIQUE (name);
    END IF;
END $$;

ON CONFLICT (name) DO NOTHING;
